preConditionHook:
// Trend resumption after a shallow pause. A strong leg ran to its extreme,
// price has since stayed inside the leg without retracing past
// maxRetraceFraction of its height, the pause has lasted no more than
// maxPauseBars, and this bar closes beyond the leg's extreme in the leg's own
// direction -- a high-conviction continuation entry. Short is the mirror.
//
// EVERY TERM IS READ OFF THE WINDOW EXTREMES; no leg detector is invented.
// Over bars 1..legLookback (bar 0 EXCLUDED, so the current bar cannot be its
// own benchmark and the breakout is a genuine one), legHigh / legLow are the
// window's extremes and hiBar / loBar the bars they printed on. The leg is
// BULL when the high came AFTER the low, hiBar < loBar; its height is
// legHigh - legLow; the pause is hiBar bars long, which is what maxPauseBars
// caps; the retracement is legHigh minus the lowest low SINCE the leg high.
// The pause range's high IS legHigh -- it is the window's highest bar and
// every pause bar lies inside the pause -- so 'closes beyond the pause range'
// is close[0] > legHigh with no extra state.
//
// UNITS: the source counts SESSIONS ('up to K sessions of pause') and this
// input counts BARS. The engine has no multi-session leg machinery; on a
// daily or 1440-minute series the two coincide exactly, and on a finer series
// maxPauseBars must be scaled in the grid. Stated rather than hidden.
// legLookback is PROMOTED -- the merged parameters gave the pause cap and the
// retracement cap but nothing bounding the leg itself.
//
// Each scan is seeded at the NEWEST offset in its range and walks outward
// with a STRICT comparison, so a tie keeps the newest bar -- the same scan
// order and tie sense as Extremes(), which Highest() and Lowest() call, and
// which is EL source and therefore carries the 2.22e-12 relational tolerance.
// The tie sense matters here because it decides hiBar and loBar, and with
// them the leg's direction.
//
// The inner scans run to hiBar / loBar, which are at least 1, so they are
// always in range and need no -1 guard. Kept whole per the merge: the pause
// and the breakout are the same claim, and the retracement cap is measured
// from a data-dependent origin, which no pane can express. Deepest bar
// touched is legLookback.
legHigh = high[1];
legLow = low[1];
hiBar = 1;
loBar = 1;
for (int j = 2; j <= (int)legLookback; ++j) {
    if (el_gt(high[j], legHigh)) {
        legHigh = high[j];
        hiBar = j;
    }
    if (el_lt(low[j], legLow)) {
        legLow = low[j];
        loBar = j;
    }
}
pauseLow = low[1];
for (int j = 2; j <= hiBar; ++j) {
    if (el_lt(low[j], pauseLow)) pauseLow = low[j];
}
pauseHigh = high[1];
for (int j = 2; j <= loBar; ++j) {
    if (el_gt(high[j], pauseHigh)) pauseHigh = high[j];
}
bullOk = (hiBar < loBar) && el_le((double)hiBar, maxPauseBars)
    && el_le(legHigh - pauseLow, maxRetraceFraction * (legHigh - legLow))
    && el_gt(close[0], legHigh);
bearOk = (loBar < hiBar) && el_le((double)loBar, maxPauseBars)
    && el_le(pauseHigh - legLow, maxRetraceFraction * (legHigh - legLow))
    && el_lt(close[0], legLow);
